#!/usr/bin/env python3
"""Build studio/models_manifest.json from Hugging Face's public file listings (read-only): for each goal, the exact files its workflow needs, with size and SHA-256 (the LFS object id) taken from the listing.
A file whose path is not in the listing is reported, never guessed. Anonymous listings mask the hashes of gated repos as asterisks: fill those with HfApi().get_paths_info under an account that has accepted the licence, because install.py compares them. Usage: python3 scripts/build_manifest.py"""
import json, sys, urllib.request
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
D, T, V, L = "diffusion_models", "text_encoders", "vae", "loras"
SPEC = {  # goal -> list of (role, repo, path in repo, models sub-folder)
 "image": ("FLUX.2 Klein 4B, 4-step distilled (Apache-2.0)", [("unet", "Comfy-Org/Flux-2-Klein-4B", "split_files/diffusion_models/flux-2-klein-4b.safetensors", D), ("text_encoder", "Comfy-Org/Flux-2-Klein-4B", "split_files/text_encoders/qwen_3_4b.safetensors", T), ("vae", "Comfy-Org/Flux-2-Klein-4B", "split_files/vae/flux2-vae.safetensors", V)]),
 "video": ("Wan 2.2 TI2V 5B (Apache-2.0); also used by Animate", [("unet", "Comfy-Org/Wan_2.2_ComfyUI_Repackaged", "split_files/diffusion_models/wan2.2_ti2v_5B_fp16.safetensors", D), ("text_encoder", "Comfy-Org/Wan_2.2_ComfyUI_Repackaged", "split_files/text_encoders/umt5_xxl_fp8_e4m3fn_scaled.safetensors", T), ("vae", "Comfy-Org/Wan_2.2_ComfyUI_Repackaged", "split_files/vae/wan2.2_vae.safetensors", V)]),
 "anime": ("Anima, anime and illustration (non-commercial licence)", [("unet", "circlestone-labs/Anima", "split_files/diffusion_models/anima-aesthetic-v1.1.safetensors", D), ("unet", "circlestone-labs/Anima", "split_files/diffusion_models/anima-turbo-v1.1.safetensors", D), ("text_encoder", "circlestone-labs/Anima", "split_files/text_encoders/qwen_3_06b_base.safetensors", T), ("vae", "circlestone-labs/Anima", "split_files/vae/qwen_image_vae.safetensors", V)]),
 "flux3": ("FLUX.3 Klein (gated: accept the licence on Hugging Face)", [("unet", "black-forest-labs/flux-3-image-klein-comfy", "diffusion_models/flux3-image-klein-bf16.safetensors", D), ("text_encoder", "black-forest-labs/flux-3-image-klein-comfy", "text_encoders/qwen3vl_4b_bf16.safetensors", T), ("vae", "black-forest-labs/flux-3-image-klein-comfy", "vae/flux2-vae.safetensors", V)]),
 "video_ltx": ("LTX-2.5 distilled, int8 (gated: accept the licence on Hugging Face)", [("unet", "Lightricks/LTX-2.5", "diffusion_models/ltx-2.5-22b-distilled-transformer-comfy-int8-convrot.safetensors", D), ("text_encoder", "Lightricks/LTX-2.5", "text_encoders/gemma4-12b-with-proj-ltx-2.5-comfy-int8-convrot.safetensors", T), ("vae", "Lightricks/LTX-2.5", "vae/ltx-2.5-video-vae-conv-bf16.safetensors", V), ("audio_vae", "Lightricks/LTX-2.5", "vae/ltx-2.5-audio-vae-bf16.safetensors", V)]),
 "h3_video": ("MiniMax H3, pruned int8 (community licence). Smaller/larger variants exist in the same repo: pruned w6a8 14.9 GB, pruned bf16 37.5 GB, bf16 61.7 GB", [("unet", "Comfy-Org/MiniMax-H3", "diffusion_models/minimax_h3_fl2va_pruned_int8_convrot.safetensors", D), ("text_encoder", "Comfy-Org/MiniMax-H3", "text_encoders/qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors", T), ("vae", "Comfy-Org/MiniMax-H3", "vae/minimax_h3_video_vae_fp16.safetensors", V), ("audio_vae", "Comfy-Org/MiniMax-H3", "vae/minimax_h3_audio_vae_fp32.safetensors", V), ("lora", "Comfy-Org/MiniMax-H3", "loras/minimax_h3_fl2v_turbo_8step_v1.0_comfyui_bf16.safetensors", L)]),
 "recast": ("MiniMax H3 Ref2VA, pruned int8, with the akatz-ai character swap LoRA (both MiniMax H3 Community License)", [("unet", "Comfy-Org/MiniMax-H3", "diffusion_models/minimax_h3_ref2va_pruned_int8_convrot.safetensors", D), ("text_encoder", "Comfy-Org/MiniMax-H3", "text_encoders/qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors", T), ("vae", "Comfy-Org/MiniMax-H3", "vae/minimax_h3_video_vae_fp16.safetensors", V), ("audio_vae", "Comfy-Org/MiniMax-H3", "vae/minimax_h3_audio_vae_fp32.safetensors", V), ("lora", "akatz-ai/MiniMax-H3-Character-Swap-LoRA", "h3_character_swap_pro4500_1000.safetensors", L)]),
 "orbit360": ("MiniMax H3 FL2VA, pruned int8, with pablodawson's 360 orbit LoRA (MiniMax H3 Community License)", [("unet", "Comfy-Org/MiniMax-H3", "diffusion_models/minimax_h3_fl2va_pruned_int8_convrot.safetensors", D), ("text_encoder", "Comfy-Org/MiniMax-H3", "text_encoders/qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors", T), ("vae", "Comfy-Org/MiniMax-H3", "vae/minimax_h3_video_vae_fp16.safetensors", V), ("lora", "pablodawson/MiniMax-H3-360-Orbit-LoRA", "minimax_h3_flf2v_lora_v1.safetensors", L)]),
 "vfx_ltx": ("LTX-2.5 distilled, int8, with four IC-LoRAs (gated: accept each licence on Hugging Face)", [("unet", "Lightricks/LTX-2.5", "diffusion_models/ltx-2.5-22b-distilled-transformer-comfy-int8-convrot.safetensors", D), ("text_encoder", "Lightricks/LTX-2.5", "text_encoders/gemma4-12b-with-proj-ltx-2.5-comfy-int8-convrot.safetensors", T), ("vae", "Lightricks/LTX-2.5", "vae/ltx-2.5-video-vae-conv-bf16.safetensors", V), ("audio_vae", "Lightricks/LTX-2.5", "vae/ltx-2.5-audio-vae-bf16.safetensors", V), ("lora", "Lightricks/LTX-2.5-22b-IC-LoRA-Clean-Plate", "ltx-2.5-22b-ic-lora-clean-plate-1.0.safetensors", L), ("lora", "Lightricks/LTX-2.5-22b-IC-LoRA-Water-Simulation", "ltx-2.5-22b-ic-lora-water-simulation-0.9.safetensors", L), ("lora", "Lightricks/LTX-2.5-22b-IC-LoRA-Day-To-Night", "ltx-2.5-22b-ic-lora-day-to-night-0.9.safetensors", L), ("lora", "Lightricks/LTX-2.5-22b-IC-LoRA-Alpha-Gen", "ltx-2.5-22b-ic-lora-alpha-gen-0.9.safetensors", L)]),
 "reshoot_wan": ("Wan 2.2 Fun Camera 14B (Apache-2.0)", [("unet", "Comfy-Org/Wan_2.2_ComfyUI_Repackaged", "split_files/diffusion_models/wan2.2_fun_camera_high_noise_14B_fp8_scaled.safetensors", D), ("unet", "Comfy-Org/Wan_2.2_ComfyUI_Repackaged", "split_files/diffusion_models/wan2.2_fun_camera_low_noise_14B_fp8_scaled.safetensors", D), ("text_encoder", "Comfy-Org/Wan_2.1_ComfyUI_repackaged", "split_files/text_encoders/umt5_xxl_fp8_e4m3fn_scaled.safetensors", T), ("vae", "Comfy-Org/Wan_2.2_ComfyUI_Repackaged", "split_files/vae/wan_2.1_vae.safetensors", V)]),
 "music": ("MiniMax Music 3 (MiniMax-Music3 community licence). The pruned bf16 encoder is the one the workflow was proven with; a pruned int8 build, 8.6 GB, exists in the same repo and the file-name resolver accepts it", [("unet", "Comfy-Org/MiniMax-Music-3", "diffusion_models/minimax_music3_dit_fp16.safetensors", D), ("text_encoder", "Comfy-Org/MiniMax-Music-3", "text_encoders/minimax_music3_text_encoder_pruned_bf16.safetensors", T), ("vae", "Comfy-Org/MiniMax-Music-3", "vae/minimax_music3_dav.safetensors", V)]),
}
def tree(repo):
    try: return {x["path"]: x for x in json.load(urllib.request.urlopen(urllib.request.Request(f"https://huggingface.co/api/models/{repo}/tree/main?recursive=1", headers={"User-Agent": "psn"}), timeout=60)) if x.get("type") == "file"}
    except Exception as e: print("ERR", repo, e); return {}
trees = {}; out = {"version": 1, "built": __import__("time").strftime("%Y-%m-%d"), "source": "Hugging Face public file listings", "goals": {}}; miss = []
for goal, (note, files) in SPEC.items():
    items = []
    for role, repo, path, sub in files:
        t = trees.setdefault(repo, tree(repo)); x = t.get(path)
        if not x: miss.append((goal, repo, path)); continue
        items.append({"role": role, "repo": repo, "path": path, "dest": f"{sub}/{Path(path).name}", "size_gb": round(x.get("size", 0) / 2**30, 2), "sha256": (x.get("lfs") or {}).get("oid", ""), "gated": repo.startswith(("black-forest-labs/", "Lightricks/"))})
    out["goals"][goal] = {"note": note, "files": items}
out["goals"]["animate"] = out["goals"]["video"]; out["goals"]["h3_animate"] = out["goals"]["h3_video"]; out["goals"]["animate_ltx"] = out["goals"]["video_ltx"]
for alias in ("reshoot", "director", "director_keyframes"): out["goals"][alias] = out["goals"]["h3_video"]
(ROOT / "studio" / "models_manifest.json").write_text(json.dumps(out, indent=1) + "\n")
for g, v in out["goals"].items(): print(f"{g:10} {len(v['files'])} files, {sum(f['size_gb'] for f in v['files']):6.1f} GB  {v['note']}")
print("not found in listing:", miss or "none")
for repo in ("Comfy-Org/MiniMax-H3", "Comfy-Org/MiniMax-Music-3"):
    t = trees.get(repo) or tree(repo); print(repo, [(p, round(x.get('size', 0) / 2**30, 1)) for p, x in t.items() if p.endswith('.safetensors') and x.get('size', 0) > 5e7][:14])
